-- Esquema inicial da versão 2.0 (banco H2 embutido).
-- Usa apenas SQL padrão (GENERATED BY DEFAULT AS IDENTITY), que também
-- funciona no PostgreSQL caso o projeto volte a usá-lo no futuro.

CREATE TABLE users (
    id       BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username VARCHAR(255) NOT NULL UNIQUE,
    password VARCHAR(255) NOT NULL,
    role     VARCHAR(255) NOT NULL,
    enabled  BOOLEAN      NOT NULL
);

CREATE TABLE cliente (
    id       BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome     VARCHAR(255),
    users_id BIGINT,
    CONSTRAINT fk_cliente_users FOREIGN KEY (users_id) REFERENCES users (id)
);

CREATE TABLE arquivo (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    apelido_arquivo  VARCHAR(255),
    caminho_arquivo  VARCHAR(255),
    nome_arquivo     VARCHAR(255),
    data_criacao     TIMESTAMP(6),
    data_atualizacao TIMESTAMP(6),
    cliente_id       BIGINT,
    CONSTRAINT fk_arquivo_cliente FOREIGN KEY (cliente_id) REFERENCES cliente (id)
);
